@@ -0,0 +1,33 @@
+-- Expand/contract step 1 of 2 for DATA-12: old code still reads/writes
+-- users.email for a few minutes after this lands, so email_address is
+-- added alongside it and kept in sync via trigger rather than renamed
+-- in place. Drop users.email and this trigger in a follow-up migration
+-- once the old code has fully rolled off.
+
+ALTER TABLE users ADD COLUMN email_address TEXT;
+UPDATE users SET email_address = email;
+ALTER TABLE users ALTER COLUMN email_address SET NOT NULL;
+ALTER TABLE users ADD CONSTRAINT users_email_address_key UNIQUE (email_address);
+
+CREATE FUNCTION sync_users_email() RETURNS trigger AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    IF NEW.email_address IS NULL THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email IS NULL THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  ELSIF TG_OP = 'UPDATE' THEN
+    IF NEW.email IS DISTINCT FROM OLD.email THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  END IF;
+  RETURN NEW;
+END;
+$$ LANGUAGE plpgsql;
+
+CREATE TRIGGER users_sync_email
+BEFORE INSERT OR UPDATE ON users
+FOR EACH ROW EXECUTE FUNCTION sync_users_email();

