index 0000000..2565695
--- /dev/null
+++ b/migrations/0003_rename_users_email_to_email_address.sql
@@ -0,0 +1,28 @@
+-- Old app instances keep reading/writing users.email for a few minutes after
+-- this lands (see README), so a straight RENAME COLUMN would break them.
+-- Add email_address alongside email and keep both in sync until a follow-up
+-- migration drops email once every instance is on the new code.
+ALTER TABLE users ADD COLUMN email_address TEXT;
+
+UPDATE users SET email_address = email;
+
+ALTER TABLE users ALTER COLUMN email_address SET NOT NULL;
+ALTER TABLE users ADD CONSTRAINT users_email_address_key UNIQUE (email_address);
+
+CREATE FUNCTION sync_users_email() RETURNS trigger AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    NEW.email := COALESCE(NEW.email, NEW.email_address);
+    NEW.email_address := COALESCE(NEW.email_address, NEW.email);
+  ELSIF NEW.email IS DISTINCT FROM OLD.email THEN
+    NEW.email_address := NEW.email;
+  ELSIF NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+    NEW.email := NEW.email_address;
+  END IF;
+  RETURN NEW;
+END;
+$$ LANGUAGE plpgsql;
+
+CREATE TRIGGER users_email_sync
+BEFORE INSERT OR UPDATE ON users
+FOR EACH ROW EXECUTE FUNCTION sync_users_email();

diff --git a/migrations/0003_users_email_address.sql b/migrations/0003_users_email_address.sql
new file mode 100644
index 0000000..e7f0fea
--- /dev/null
+++ b/migrations/0003_users_email_address.sql
@@ -0,0 +1,108 @@
+-- Old app instances keep reading/writing `email` for a few minutes after this
+-- lands (see README), so this can't be a straight RENAME COLUMN. Add the new
+-- column and keep both in sync; a follow-up migration drops `email` once the
+-- app has cut over to `email_address`.
+--
+-- This migration must run with autocommit (one statement per transaction),
+-- not wrapped in a single outer transaction: CREATE INDEX CONCURRENTLY and
+-- the batched backfill's per-batch COMMIT both require that.
+
+-- Adding a nullable column with no default is a metadata-only change in
+-- Postgres 11+ and does not rewrite the table.
+ALTER TABLE users ADD COLUMN IF NOT EXISTS email_address TEXT;
+
+-- Install the sync trigger before anything below that could reject a
+-- concurrent write (the NOT NULL enforcement further down): old app
+-- instances writing only `email` for a few minutes after this lands (see
+-- README) must never see `email_address` left NULL.
+CREATE OR REPLACE FUNCTION sync_users_email_columns() RETURNS TRIGGER AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    -- If both columns are supplied with different values, `email_address`
+    -- (the new canonical column) wins.
+    IF NEW.email_address IS NULL THEN
+      NEW.email_address := NEW.email;
+    ELSE
+      NEW.email := NEW.email_address;
+    END IF;
+  ELSE
+    IF NEW.email IS DISTINCT FROM OLD.email AND NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+      -- Both changed in the same statement to different values;
+      -- `email_address` wins rather than letting the columns diverge silently.
+      NEW.email := NEW.email_address;
+    ELSIF NEW.email IS DISTINCT FROM OLD.email THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  END IF;
+  RETURN NEW;
+END;
+$$ LANGUAGE plpgsql;
+
+DROP TRIGGER IF EXISTS users_email_columns_sync ON users;
+CREATE TRIGGER users_email_columns_sync
+BEFORE INSERT OR UPDATE ON users
+FOR EACH ROW EXECUTE FUNCTION sync_users_email_columns();
+
+-- Fail fast with a clear error instead of aborting deep inside the NOT
+-- NULL / UNIQUE steps below with an opaque constraint-violation error.
+DO $$
+DECLARE
+  null_count BIGINT;
+  dup_count BIGINT;
+BEGIN
+  SELECT count(*) INTO null_count FROM users WHERE email IS NULL;
+  IF null_count > 0 THEN
+    RAISE EXCEPTION 'users.email has % NULL row(s); backfill/dedupe before running this migration', null_count;
+  END IF;
+
+  SELECT count(*) INTO dup_count FROM (
+    SELECT email FROM users GROUP BY email HAVING count(*) > 1
+  ) d;
+  IF dup_count > 0 THEN
+    RAISE EXCEPTION 'users.email has % duplicate value(s); dedupe before running this migration', dup_count;
+  END IF;
+END $$;
+
+-- Backfill in batches so no single statement holds a long lock or generates
+-- a huge amount of WAL; each batch commits independently. A plain DO block
+-- can't COMMIT, so this uses a throwaway procedure invoked outside a
+-- transaction block.
+CREATE OR REPLACE PROCEDURE backfill_users_email_address(batch_size INT DEFAULT 5000)
+LANGUAGE plpgsql AS $$
+DECLARE
+  rows_updated INT;
+BEGIN
+  LOOP
+    UPDATE users
+    SET email_address = email
+    WHERE id IN (
+      SELECT id FROM users WHERE email_address IS NULL LIMIT batch_size
+    );
+    GET DIAGNOSTICS rows_updated = ROW_COUNT;
+    COMMIT;
+    EXIT WHEN rows_updated = 0;
+  END LOOP;
+END;
+$$;
+
+CALL backfill_users_email_address();
+
+DROP PROCEDURE backfill_users_email_address(INT);
+
+-- Enforce NOT NULL without a full-table ACCESS EXCLUSIVE scan: validate a
+-- NOT VALID check constraint first (VALIDATE CONSTRAINT takes SHARE UPDATE
+-- EXCLUSIVE, which doesn't block reads/writes), then SET NOT NULL, which
+-- Postgres can skip re-scanning the table for because the validated
+-- constraint already proves the invariant.
+ALTER TABLE users ADD CONSTRAINT email_address_not_null CHECK (email_address IS NOT NULL) NOT VALID;
+ALTER TABLE users VALIDATE CONSTRAINT email_address_not_null;
+ALTER TABLE users ALTER COLUMN email_address SET NOT NULL;
+ALTER TABLE users DROP CONSTRAINT email_address_not_null;
+
+-- Enforce UNIQUE without a long lock: build the index CONCURRENTLY (doesn't
+-- block reads/writes), then attach it as a constraint, which is fast because
+-- the index already exists.
+CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS users_email_address_key ON users (email_address);
+ALTER TABLE users ADD CONSTRAINT users_email_address_key UNIQUE USING INDEX users_email_address_key;
